import json
import subprocess, sys


def run(*args):
    return subprocess.run([sys.executable, "wc.py", *args], capture_output=True, text=True)


def test_text_output_is_unchanged():
    out = subprocess.run([sys.executable, "wc.py", "sample.txt"], capture_output=True, text=True, check=True).stdout
    assert out.splitlines()[:4] == ["lines: 4", "words: 12", "unique: 8", "the 3"]


def test_top_limits_text_output():
    out = run("sample.txt", "--top", "2").stdout
    assert out.splitlines() == ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2"]


def test_top_before_filename():
    out = run("--top", "2", "sample.txt").stdout
    assert out.splitlines() == ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2"]


def test_top_keeps_tie_order():
    out = run("sample.txt", "--top", "6").stdout
    assert out.splitlines()[3:] == ["the 3", "cat 2", "sat 2", "ran 1", "a 1", "dog 1"]


def test_json_output():
    p = run("sample.txt", "--json")
    assert p.returncode == 0
    data = json.loads(p.stdout)
    assert data == {"lines": 4, "words": 12, "unique": 8,
                    "top": [["the", 3], ["cat", 2], ["sat", 2], ["ran", 1], ["a", 1]]}


def test_json_top_and_option_order():
    data = json.loads(run("--json", "--top", "3", "sample.txt").stdout)
    assert data["top"] == [["the", 3], ["cat", 2], ["sat", 2]]


def test_missing_file_message_and_exit_code():
    p = run("no-such-file.txt")
    assert p.returncode == 2
    assert p.stderr == "error: no such file: no-such-file.txt\n"
    assert p.stdout == ""

